#[cfg(test)]
mod extend_204115_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_extend_204115_codec() {
        let original = Extend204115 {
            cash_margin: "a".to_string(),
            settl_type: 1234,
            settl_period: 42,
            counterparty_member_id: "a".repeat(6),
            counterparty_investor_type: "a".repeat(2),
            counterparty_investor_id: "a".repeat(10),
            counterparty_investor_name: "a".repeat(120),
            counterparty_trader_code: "a".repeat(8),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(Extend204115Ref::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        Extend204115::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = Extend204115::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

